import{_ as a,o as l,c as o,a7 as t}from"./chunks/framework.FWlv_suP.js";const h=JSON.parse('{"title":"LocalTell Data Deletion","description":"Official data deletion information for LocalTell.","frontmatter":{"title":"LocalTell Data Deletion","description":"Official data deletion information for LocalTell.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-deletion/local-tell.md","filePath":"data-deletion/local-tell.md"}'),r={name:"data-deletion/local-tell.md"};function n(s,e,i,d,c,p){return l(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="delete-localtell-data" tabindex="-1">Delete LocalTell Data <a class="header-anchor" href="#delete-localtell-data" aria-label="Permalink to &quot;Delete LocalTell Data&quot;">​</a></h1><p>LocalTell has no online account or developer-operated cloud database. Its data is stored on your Android device.</p><h2 id="remove-an-offline-pack" tabindex="-1">Remove an offline pack <a class="header-anchor" href="#remove-an-offline-pack" aria-label="Permalink to &quot;Remove an offline pack&quot;">​</a></h2><p>Open <strong>Offline data</strong>, select an installed pack, and choose <strong>Remove</strong>. This removes that local pack from LocalTell.</p><h2 id="clear-journey-history" tabindex="-1">Clear Journey history <a class="header-anchor" href="#clear-journey-history" aria-label="Permalink to &quot;Clear Journey history&quot;">​</a></h2><p>Open <strong>Journey</strong> and choose <strong>Clear</strong> to remove the locally stored Journey entries.</p><h2 id="delete-all-local-data" tabindex="-1">Delete all local data <a class="header-anchor" href="#delete-all-local-data" aria-label="Permalink to &quot;Delete all local data&quot;">​</a></h2><p>Clear LocalTell storage in Android system settings or uninstall the app. This removes LocalTell&#39;s app-private offline packs, preferences, and Journey history. Android backup and device transfer do not retain this app data.</p><p>Because the developer does not receive or store this data, emailing support cannot delete records from your device.</p>',9)])])}const u=a(r,[["render",n]]);export{h as __pageData,u as default};
